import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';import {embedActivity} from '../scripts/embed-l3-activity-20261016.mjs';
const source=readFileSync(new URL('../apps/pet-l3-activity-20261016.js',import.meta.url),'utf8');
function page(){let now=Date.now();const nodes=[],handlers={},timers=[];class E{constructor(){this.children=[];this.dataset={};this.attrs={};this.scrollHeight=50;this.scrollTop=0;this.clientHeight=100;nodes.push(this);}append(...e){this.children.push(...e);}prepend(e){this.children.unshift(e);}replaceChildren(){this.children=[];this.replaced=(this.replaced||0)+1;}setAttribute(k,v){this.attrs[k]=v;}insertAdjacentElement(_,e){this.append(e);}}
const header=new E(),ctx={document:{querySelector:s=>s==='[data-astra-l3-config]'?{textContent:'{"repo":"sample","pet":"Sample"}'}:s==='header'?header:null,createElement:()=>new E(),addEventListener:(n,f)=>handlers[n]=f,readyState:'complete'},window:{},Date:class extends Date{static now(){return now;}},setInterval:f=>timers.push(f)};vm.runInNewContext(source,ctx);return{nodes,view:()=>header.children[0],send:x=>ctx.window.astraL3Activity.receive({repo:'sample',at:new Date(now).toISOString(),...x}),advance:ms=>{now+=ms;timers.forEach(f=>f());},ctx};}
test('empty page is disconnected and does not create activity',()=>{const p=page();assert.equal(p.view().dataset.state,'disconnected');assert.match(p.view().children[1].textContent,/No L3/);assert.equal(p.view().children[3].children[0].textContent,'No activity received.');});
test('reject mismatched pet, invalid status, future and out-of-order updates',()=>{const p=page();assert.equal(p.send({repo:'other',status:'working'}),false);assert.equal(p.send({status:'invented'}),false);assert.equal(p.send({status:'working',at:'bad'}),false);assert.equal(p.send({status:'working',at:new Date(Date.now()+60000).toISOString()}),false);assert.equal(p.send({status:'working'}),true);assert.equal(p.send({status:'idle',at:new Date(Date.now()-60000).toISOString()}),false);});
test('actual snapshots are bounded text, duplicate polling does not rewrite log',()=>{const p=page(),x={status:'working',provider:'test fixture',events:Array.from({length:90},(_,i)=>({at:new Date().toISOString(),message:i+' <img onerror=unsafe>'}))};p.send(x);const log=p.view().children[3];assert.equal(log.children.length,80);assert.match(log.children[0].textContent,/10 <img onerror=unsafe>/);const renders=log.replaced;p.send(x);assert.equal(log.replaced,renders);});
test('stale feed, OFF, error and disconnect never remain working',()=>{const p=page();p.send({status:'working'});p.advance(121000);assert.equal(p.view().dataset.state,'stale');for(const status of ['off','error','disconnected']){p.send({status});assert.equal(p.view().dataset.state,status);}});
test('embedding is idempotent and preserves host handlers',()=>{const src='<html><body><script>host.handler=42;</script></body></html>';const one=embedActivity(src,'github-goldfish');assert.equal(embedActivity(one,'github-goldfish'),one);assert.ok(one.includes('<script>host.handler=42;</script>'));assert.equal(one.match(/<!--astra-l3-start-->/g).length,1);});
